// Group the engine's complete catalogue with its corresponding monthly charts.
import {formatKpi} from './kpis.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const CHART_FAMILIES={backlog:'work',cases:'work',reads:'reading',cost:'cost',blocked:'billing',cash:'cash',ar:'cash',dunning:'cash',phases:'cash',contacts:'contact',service:'contact',contactCost:'contact',contactEffects:'contact',fieldDone:'field',fieldBacklog:'field',fieldOnTime:'field',fieldEffects:'field',fieldCost:'field'};
export const commandKpiKey=client=>JSON.stringify(client.body({asOf:client.asOf}));

export function kpiDashboard(catalogue,values,{watched=[],asOf='',thresholds={},href='./glossary.html',charts=[],closed=new Set(),loading=false,error=''}={}){
 const groups=(catalogue?.families||[]).map(f=>({...f,kpis:(catalogue.kpis||[]).filter(k=>k.family===f.id),charts:charts.filter(c=>CHART_FAMILIES[c.id]===f.id)})).filter(f=>f.kpis.length||f.charts.length);
 const selected=new Set(watched),loadingValues=values==null&&!error;
 const tile=k=>{const value=values?.[k.id],missing=value==null;
  const windows=(k.thresholds||[]).map(p=>{const meta=catalogue.thresholds?.[p]||{},v=thresholds[p]??meta.value;return `${meta.title||p}: ${v??'—'} ${meta.unit||''}`;});
  return `<article class="kpi-result${selected.has(k.id)?' is-watched':''}" data-kpi="${esc(k.id)}"><header><h4>${esc(k.title)}</h4>${selected.has(k.id)?'<span class="kpi-watched">Watched</span>':''}</header><strong class="kpi-result-value">${loadingValues?'…':esc(formatKpi(value,k.unit))}</strong><p class="kpi-result-caption">${loadingValues?'Updating…':value===undefined?'Unavailable':missing?'No applicable records':k.better==='context'?'Context measure':esc(k.better)+' is better'}</p><details class="kpi-definition"><summary>Definition</summary><p>${esc(k.definition)}</p><code>${esc(k.formula)}</code>${windows.length?`<p>${esc(windows.join(' · '))}</p>`:''}<a href="${esc(href.split('#')[0])}#${encodeURIComponent(k.id)}" target="_blank" rel="noopener">Full definition ↗</a><button type="button" class="small-link" data-kpi-dependencies="${esc(k.id)}">Trace dependencies →</button></details></article>`;};
 const status=error?`<p class="year-error" role="alert">${esc(error)} <button type="button" class="small-link" data-kpi-retry>Retry KPI results</button></p>`:loading?'<p class="small-note" role="status">Updating the figures for this run…</p>':'';
 return `<section class="year-results" aria-label="Utility performance"><header class="kpi-dashboard-head"><div><span class="section-kicker">UTILITY PERFORMANCE</span><h2>Every measure, in one place</h2><p>${catalogue?.kpis?.length||'All'} KPIs${asOf?' · through '+esc(asOf):''} · grouped by the work they describe</p></div><a href="${esc(href)}" target="_blank" rel="noopener">Definitions &amp; report coverage ↗</a></header>${status}${groups.length?`<nav class="kpi-group-nav" aria-label="KPI groups">${groups.map(f=>`<button type="button" data-kpi-jump="${esc(f.id)}">${esc(f.title)} <span>${f.kpis.length}</span></button>`).join('')}</nav><p class="kpi-dashboard-note">Values follow each measure’s definition: year-to-date activity or the position on the run date. A dash means no applicable records or an unavailable measure.</p>${groups.map(f=>`<details class="kpi-family" data-kpi-family="${esc(f.id)}" ${closed.has(f.id)?'':'open'}><summary><span><strong>${esc(f.title)}</strong><small>${esc(f.text)}</small></span><span class="kpi-family-count">${f.kpis.length} KPIs</span></summary><div class="kpi-family-body"><div class="kpi-family-values">${f.kpis.map(tile).join('')}</div>${f.charts.length?`<h4 class="kpi-monthly-heading">Month by month</h4><div class="year-trends" aria-label="${esc(f.title)} monthly trends">${f.charts.map(c=>c.html).join('')}</div>`:''}</div></details>`).join('')}`:error?'':'<p class="small-note" role="status">Loading the KPI catalogue…</p>'}</section>`;
}
